104	func parseOptOrder(d *caddyfile.Dispenser, existingVal any) (any, error) {
105		d.Next() // consume option name
106	
107		// get directive name
108		if !d.Next() {
109			return nil, d.ArgErr()
110		}
111		dirName := d.Val()
112		if _, ok := registeredDirectives[dirName]; !ok {
113			return nil, d.Errf("%s is not a registered directive", dirName)
114		}
115	
116		// Reorder for this adaptation only. A previous "order" global option in
117		// the same adaptation passes its resulting order as existingVal; the
118		// first one builds on the registered baseline. The package-level
119		// directiveOrder is never mutated, so concurrent adaptations cannot leak
120		// their ordering into each other. Copy before rearranging: slices.DeleteFunc
121		// and slices.Insert edit the backing array in place, and the baseline may
122		// be the package-level slice.
123		var baseOrder []string
124		if existing, ok := existingVal.([]string); ok {
125			baseOrder = append(baseOrder, existing...)
126		} else {
127			baseOrder = append(baseOrder, directiveOrder...)
128		}
129	
130		// get positional token
131		if !d.Next() {
132			return nil, d.ArgErr()
133		}
134		pos := Positional(d.Val())
135	
136		// if directive already had an order, drop it
137		newOrder := slices.DeleteFunc(baseOrder, func(d string) bool {
138			return d == dirName
139		})
140	
141		// act on the positional; if it's First or Last, we're done right away
142		switch pos {
143		case First:
144			newOrder = append([]string{dirName}, newOrder...)
145			if d.NextArg() {
146				return nil, d.ArgErr()
147			}
148			return newOrder, nil
149	
150		case Last:
151			newOrder = append(newOrder, dirName)
152			if d.NextArg() {
153				return nil, d.ArgErr()
154			}
155			return newOrder, nil
156	
157		// if it's Before or After, continue
158		case Before:
159		case After:
160	
161		default:
162			return nil, d.Errf("unknown positional '%s'", pos)
163		}
164	
165		// get name of other directive
166		if !d.NextArg() {
167			return nil, d.ArgErr()
168		}
169		otherDir := d.Val()
170		if d.NextArg() {
171			return nil, d.ArgErr()
172		}
173	
174		// get the position of the target directive
175		targetIndex := slices.Index(newOrder, otherDir)
176		if targetIndex == -1 {
177			return nil, d.Errf("directive '%s' not found", otherDir)
178		}
179		// if we're inserting after, we need to increment the index to go after
180		if pos == After {
181			targetIndex++
182		}
183		// insert the directive into the new order
184		newOrder = slices.Insert(newOrder, targetIndex, dirName)
185	
186		return newOrder, nil
187	}
