189	func parseOptStorage(d *caddyfile.Dispenser, _ any) (any, error) {
190		if !d.Next() { // consume option name
191			return nil, d.ArgErr()
192		}
193		if !d.Next() { // get storage module name
194			return nil, d.ArgErr()
195		}
196		modID := "caddy.storage." + d.Val()
197		unm, err := caddyfile.UnmarshalModule(d, modID)
198		if err != nil {
199			return nil, err
200		}
201		storage, ok := unm.(caddy.StorageConverter)
202		if !ok {
203			return nil, d.Errf("module %s is not a caddy.StorageConverter", modID)
204		}
205		return storage, nil
206	}
