256	func parseOptACMEEAB(d *caddyfile.Dispenser, _ any) (any, error) {
257		eab := new(acme.EAB)
258		d.Next() // consume option name
259		if d.NextArg() {
260			return nil, d.ArgErr()
261		}
262		for d.NextBlock(0) {
263			switch d.Val() {
264			case "key_id":
265				if !d.NextArg() {
266					return nil, d.ArgErr()
267				}
268				eab.KeyID = d.Val()
269	
270			case "mac_key":
271				if !d.NextArg() {
272					return nil, d.ArgErr()
273				}
274				eab.MACKey = d.Val()
275	
276			default:
277				return nil, d.Errf("unrecognized parameter '%s'", d.Val())
278			}
279		}
280		return eab, nil
281	}
