283	func parseOptCertIssuer(d *caddyfile.Dispenser, existing any) (any, error) {
284		d.Next() // consume option name
285	
286		var issuers []certmagic.Issuer
287		if existing != nil {
288			issuers = existing.([]certmagic.Issuer)
289		}
290	
291		// get issuer module name
292		if !d.Next() {
293			return nil, d.ArgErr()
294		}
295		modID := "tls.issuance." + d.Val()
296		unm, err := caddyfile.UnmarshalModule(d, modID)
297		if err != nil {
298			return nil, err
299		}
300		iss, ok := unm.(certmagic.Issuer)
301		if !ok {
302			return nil, d.Errf("module %s (%T) is not a certmagic.Issuer", modID, unm)
303		}
304		issuers = append(issuers, iss)
305		return issuers, nil
306	}
