329	func parseOptDefaultBind(d *caddyfile.Dispenser, _ any) (any, error) {
330		d.Next() // consume option name
331	
332		var addresses, protocols []string
333		addresses = d.RemainingArgs()
334	
335		if len(addresses) == 0 {
336			addresses = append(addresses, "")
337		}
338	
339		for d.NextBlock(0) {
340			switch d.Val() {
341			case "protocols":
342				protocols = d.RemainingArgs()
343				if len(protocols) == 0 {
344					return nil, d.Errf("protocols requires one or more arguments")
345				}
346			default:
347				return nil, d.Errf("unknown subdirective: %s", d.Val())
348			}
349		}
350	
351		return []ConfigValue{{Class: "bind", Value: addressesWithProtocols{
352			addresses: addresses,
353			protocols: protocols,
354		}}}, nil
355	}
