454	func parseOptPersistConfig(d *caddyfile.Dispenser, _ any) (any, error) {
455		d.Next() // consume option name
456		if !d.Next() {
457			return "", d.ArgErr()
458		}
459		val := d.Val()
460		if d.Next() {
461			return "", d.ArgErr()
462		}
463		if val != "off" {
464			return "", d.Errf("persist_config must be 'off'")
465		}
466		return val, nil
467	}
468	
469	func parseOptAutoHTTPS(d *caddyfile.Dispenser, _ any) (any, error) {
470		d.Next() // consume option name
471		val := d.RemainingArgs()
472		if len(val) == 0 {
473			return "", d.ArgErr()
474		}
475		for _, v := range val {
476			switch v {
477			case "off":
478			case "disable_redirects":
479			case "disable_certs":
480			case "ignore_loaded_certs":
481			default:
482				return "", d.Errf("auto_https must be one of 'off', 'disable_redirects', 'disable_certs', or 'ignore_loaded_certs'")
483			}
484		}
485		return val, nil
486	}
487	
488	func unmarshalCaddyfileMetricsOptions(d *caddyfile.Dispenser) (any, error) {
489		d.Next() // consume option name
490		metrics := new(caddyhttp.Metrics)
491		for d.NextBlock(0) {
492			switch d.Val() {
493			case "per_host":
494				metrics.PerHost = true
495			case "observe_catchall_hosts":
496				metrics.ObserveCatchallHosts = true
497			case "otlp":
498				metrics.OTLP = true
499			default:
500				return nil, d.Errf("unrecognized servers option '%s'", d.Val())
501			}
502		}
503		return metrics, nil
504	}
505	
506	func parseMetricsOptions(d *caddyfile.Dispenser, _ any) (any, error) {
507		return unmarshalCaddyfileMetricsOptions(d)
508	}
509	
510	func parseServerOptions(d *caddyfile.Dispenser, _ any) (any, error) {
511		return unmarshalCaddyfileServerOptions(d)
512	}
513	
514	func parseOCSPStaplingOptions(d *caddyfile.Dispenser, _ any) (any, error) {
515		d.Next() // consume option name
516		var val string
517		if !d.AllArgs(&val) {
518			return nil, d.ArgErr()
519		}
520		if val != "off" {
521			return nil, d.Errf("invalid argument '%s'", val)
522		}
523		return certmagic.OCSPConfig{
524			DisableStapling: val == "off",
525		}, nil
526	}
527	
528	// parseLogOptions parses the global log option. Syntax:
529	//
530	//	log [name] {
531	//	    output  <writer_module> ...
532	//	    format  <encoder_module> ...
533	//	    level   <level>
534	//	    include <namespaces...>
535	//	    exclude <namespaces...>
536	//	}
537	//
538	// When the name argument is unspecified, this directive modifies the default
539	// logger.
540	func parseLogOptions(d *caddyfile.Dispenser, existingVal any) (any, error) {
541		currentNames := make(map[string]struct{})
542		if existingVal != nil {
543			innerVals, ok := existingVal.([]ConfigValue)
544			if !ok {
545				return nil, d.Errf("existing log values of unexpected type: %T", existingVal)
546			}
547			for _, rawVal := range innerVals {
548				val, ok := rawVal.Value.(namedCustomLog)
549				if !ok {
550					return nil, d.Errf("existing log value of unexpected type: %T", existingVal)
551				}
552				currentNames[val.name] = struct{}{}
553			}
554		}
555	
556		var warnings []caddyconfig.Warning
557		// Call out the same parser that handles server-specific log configuration.
558		configValues, err := parseLogHelper(
559			Helper{
560				Dispenser: d,
561				warnings:  &warnings,
562			},
563			currentNames,
564		)
565		if err != nil {
566			return nil, err
567		}
568		if len(warnings) > 0 {
569			return nil, d.Errf("warnings found in parsing global log options: %+v", warnings)
570		}
571	
572		return configValues, nil
573	}
574	
575	func parseOptPreferredChains(d *caddyfile.Dispenser, _ any) (any, error) {
576		d.Next()
577		return caddytls.ParseCaddyfilePreferredChainsOptions(d)
578	}
579	
580	func parseOptDNS(d *caddyfile.Dispenser, _ any) (any, error) {
581		d.Next() // consume option name
582		optName := d.Val()
583	
584		// get DNS module name
585		if !d.Next() {
586			// this is allowed if this is the "acme_dns" option since it may refer to the globally-configured "dns" option's value
587			if optName == "acme_dns" {
588				return nil, nil
589			}
590			return nil, d.ArgErr()
591		}
592		modID := "dns.providers." + d.Val()
593		unm, err := caddyfile.UnmarshalModule(d, modID)
594		if err != nil {
595			return nil, err
596		}
597		switch unm.(type) {
598		case libdns.RecordGetter,
599			libdns.RecordSetter,
600			libdns.RecordAppender,
601			libdns.RecordDeleter:
602		default:
603			return nil, d.Errf("module %s (%T) is not a libdns provider", modID, unm)
604		}
605		return unm, nil
606	}
607	
608	func parseOptECH(d *caddyfile.Dispenser, _ any) (any, error) {
609		d.Next() // consume option name
610	
611		ech := new(caddytls.ECH)
612	
613		publicNames := d.RemainingArgs()
614		for _, publicName := range publicNames {
615			ech.Configs = append(ech.Configs, caddytls.ECHConfiguration{
616				PublicName: publicName,
617			})
618		}
619		if len(ech.Configs) == 0 {
620			return nil, d.ArgErr()
621		}
622	
623		for nesting := d.Nesting(); d.NextBlock(nesting); {
624			switch d.Val() {
625			case "dns":
626				if !d.Next() {
627					return nil, d.ArgErr()
628				}
629				providerName := d.Val()
630				modID := "dns.providers." + providerName
631				unm, err := caddyfile.UnmarshalModule(d, modID)
632				if err != nil {
633					return nil, err
634				}
635				ech.Publication = append(ech.Publication, &caddytls.ECHPublication{
636					Configs: publicNames,
637					PublishersRaw: caddy.ModuleMap{
638						"dns": caddyconfig.JSON(caddytls.ECHDNSPublisher{
639							ProviderRaw: caddyconfig.JSONModuleObject(unm, "name", providerName, nil),
640						}, nil),
641					},
642				})
643			default:
644				return nil, d.Errf("ech: unrecognized subdirective '%s'", d.Val())
645			}
646		}
647	
648		return ech, nil
649	}
650	
651	func parseOptRenewalWindowRatio(d *caddyfile.Dispenser, _ any) (any, error) {
652		d.Next() // consume option name
653		if !d.Next() {
654			return 0, d.ArgErr()
655		}
656		val := d.Val()
657		ratio, err := strconv.ParseFloat(val, 64)
658		if err != nil {
659			return 0, d.Errf("parsing renewal_window_ratio: %v", err)
660		}
661		if ratio <= 0 || ratio >= 1 {
662			return 0, d.Errf("renewal_window_ratio must be between 0 and 1 (exclusive)")
663		}
664		if d.Next() {
665			return 0, d.ArgErr()
666		}
667		return ratio, nil
668	}
