29		"github.com/caddyserver/caddy/v2/caddyconfig/caddyfile"
30	)
31	
32	// The trees below share one site shape: a redir followed (lexically) by a
33	// respond. In the default directive order redir runs first; the ALPHA tree
34	// flips that with the "order" global option so respond runs first. The
35	// adapted JSON therefore differs between the trees and reveals any leakage
36	// of one call's directive order into the other. Each tree also exercises
37	// nested, globbed and relative imports, which contribute header directives
38	// and anchor the diagnostics to the tree's own files.
39	func writeOrderTree(t *testing.T, dir, host string) {
40		t.Helper()
41		marker := strings.SplitN(host, "-", 2)[0] // "alpha" or "bravo"
42		write := func(rel, content string) {
43			writeAdaptFile(t, filepath.Join(dir, rel), content)
44		}
45		write(filepath.Join(marker, "sub", "deep.caddy"), "vars deep "+marker+"\n")
46		write(filepath.Join(marker, "dir.caddy"), "import sub/../sub/deep.caddy\n")
47		write(filepath.Join(marker, "parts", "p1.caddy"), "vars glob "+marker+"\n")
48		write(filepath.Join(marker, "site.caddy"), strings.Join([]string{
49			"import dir.caddy",
50			"import parts/*.caddy",
51			"redir /" + marker + "-old /" + marker + "-new",
52			`respond "` + strings.ToUpper(marker) + `"`,
53		}, "\n")+"\n")
54	}
55	
56	func alphaBody() []byte {
57		return []byte(`{
58		order respond before redir
59	}
60	alpha-iso.example {
61		import alpha/site.caddy
62	}
63	`)
64	}
65	
66	func bravoBody() []byte {
67		return []byte(`bravo-iso.example {
68		import bravo/site.caddy
69	}
70	`)
71	}
72	
73	type adaptResult struct {
74		out      []byte
75		warnings []caddyconfig.Warning
76		err      error
77	}
78	
79	func runAdapt(t *testing.T, adapter caddyfile.Adapter, root string, body []byte) adaptResult {
80		t.Helper()
81		out, warnings, err := adapter.Adapt(body, map[string]any{"filename": root})
82		return adaptResult{out: out, warnings: warnings, err: err}
83	}
84	
85	// redirRespondOrder decodes the site subroute and returns the relative
86	// pipeline order of the redir (a static_response carrying status 302) and
87	// the plain respond (a static_response carrying a body). Headers are
88	// ignored.
89	func redirRespondOrder(t *testing.T, out []byte) []string {
90		t.Helper()
91		var doc struct {
92			Apps struct {
93				HTTP struct {
94					Servers map[string]struct {
95						Routes []struct {
96							Handle []struct {
97								Routes []struct {
98									Handle []struct {
99										StatusCode int    `json:"status_code"`
100										Body       string `json:"body"`
101									} `json:"handle"`
102								} `json:"routes"`
103							} `json:"handle"`
104						} `json:"routes"`
105					} `json:"servers"`
106				} `json:"http"`
107			} `json:"apps"`
108		}
109		if err := json.Unmarshal(out, &doc); err != nil {
110			t.Fatalf("unmarshaling adapted JSON: %v\n%s", err, out)
111		}
112		var order []string
113		for _, srv := range doc.Apps.HTTP.Servers {
114			for _, route := range srv.Routes {
115				for _, h := range route.Handle {
116					for _, sr := range h.Routes {
117						for _, hh := range sr.Handle {
118							if hh.StatusCode == 302 {
119								order = append(order, "redir")
120							} else if hh.Body != "" {
121								order = append(order, "respond")
122							}
123						}
124					}
125				}
126			}
127		}
128		return order
129	}
130	
131	func expectHandlerOrder(t *testing.T, label string, out []byte, wantFirst, wantSecond string) {
132		t.Helper()
133		order := redirRespondOrder(t, out)
134		redirAt, respondAt := indexOf(order, "redir"), indexOf(order, "respond")
135		if redirAt < 0 || respondAt < 0 {
136			t.Fatalf("%s: expected one redir and one respond, got %v", label, order)
137		}
138		gotFirst, gotSecond := "redir", "respond"
139		if respondAt < redirAt {
140			gotFirst, gotSecond = "respond", "redir"
141		}
142		if gotFirst != wantFirst || gotSecond != wantSecond {
143			t.Errorf("%s: expected %s before %s, got pipeline %v", label, wantFirst, wantSecond, order)
144		}
145	}
146	
147	func indexOf(s []string, v string) int {
148		for i, x := range s {
149			if x == v {
150				return i
151			}
152		}
153		return -1
154	}
155	
156	func assertResultEqual(t *testing.T, label string, got, want adaptResult) {
157		t.Helper()
158		if (got.err == nil) != (want.err == nil) {
159			t.Fatalf("%s: error presence drift: want %v, got %v", label, want.err, got.err)
160		}
161		if want.err != nil && got.err.Error() != want.err.Error() {
162			t.Errorf("%s: error text drift\nwant: %s\ngot:  %s", label, want.err, got.err)
163		}
164		if !bytes.Equal(got.out, want.out) {
165			t.Errorf("%s: body drift\nwant: %s\ngot:  %s", label, want.out, got.out)
166		}
167		if !reflect.DeepEqual(got.warnings, want.warnings) {
168			t.Errorf("%s: warnings drift\nwant: %v\ngot:  %v", label, want.warnings, got.warnings)
169		}
170	}
171	
172	// TestAdaptConcurrentDirectiveOrderIsolation drives one shared
173	// caddyfile.Adapter (with the real HTTP ServerType) concurrently from two
174	// disjoint file trees: one uses the "order" global option to reorder
175	// respond before redir, the other relies on the default order. Neither the
176	// returned JSON, the warnings, nor the error of one call may reflect the
177	// other call's tree or directive order: this both detects data races (run
178	// under -race) and semantic cross-talk through process-wide state mutated
179	// while adapting.
180	func TestAdaptConcurrentDirectiveOrderIsolation(t *testing.T) {
181		const (
182			workers    = 8
183			iterations = 4
184		)
185	
186		alphaDir := t.TempDir()
187		bravoDir := t.TempDir()
188		writeOrderTree(t, alphaDir, "alpha-iso")
189		writeOrderTree(t, bravoDir, "bravo-iso")
190		alphaRoot := filepath.Join(alphaDir, "Caddyfile")
191		bravoRoot := filepath.Join(bravoDir, "Caddyfile")
192		aBody, bBody := alphaBody(), bravoBody()
193	
194		// Serial references computed as if each tree were adapted in isolation.
195		// bravo (default order) is evaluated first, before any "order" option has
196		// run, so its reference represents a process that only ever saw bravo.
197		fresh := caddyfile.Adapter{ServerType: ServerType{}}
198		wantBravo := runAdapt(t, fresh, bravoRoot, bBody)
199		if wantBravo.err != nil {
200			t.Fatalf("bravo reference failed: %v", wantBravo.err)
201		}
202		wantAlpha := runAdapt(t, fresh, alphaRoot, aBody)
203		if wantAlpha.err != nil {
204			t.Fatalf("alpha reference failed: %v", wantAlpha.err)
205		}
206		expectHandlerOrder(t, "alpha reference", wantAlpha.out, "respond", "redir")
207		expectHandlerOrder(t, "bravo reference", wantBravo.out, "redir", "respond")
208		if bytes.Contains(wantAlpha.out, []byte("bravo")) || bytes.Contains(wantBravo.out, []byte("alpha")) {
209			t.Fatal("reference bodies already leak between trees")
210		}
211	
212		shared := caddyfile.Adapter{ServerType: ServerType{}}
213	
214		runBatch := func(alphaFirst bool) {
215			t.Helper()
216			start := make(chan struct{})
217			var wg sync.WaitGroup
218			var mu sync.Mutex
219			var alphaResults, bravoResults []adaptResult
220	
221			launch := func(body []byte, root string, sink *[]adaptResult) {
222				defer wg.Done()
223				<-start
224				res := runAdapt(t, shared, root, body)
225				mu.Lock()
226				*sink = append(*sink, res)
227				mu.Unlock()
228			}
229	
230			for i := 0; i < workers; i++ {
231				wg.Add(2)
232				if alphaFirst {
233					go launch(aBody, alphaRoot, &alphaResults)
234					go launch(bBody, bravoRoot, &bravoResults)
235				} else {
236					go launch(bBody, bravoRoot, &bravoResults)
237					go launch(aBody, alphaRoot, &alphaResults)
238				}
239			}
240			close(start)
241			wg.Wait()
242	
243			if len(alphaResults) != workers || len(bravoResults) != workers {
244				t.Fatalf("expected %d results per tree, got %d alpha / %d bravo",
245					workers, len(alphaResults), len(bravoResults))
246			}
247			for i, res := range alphaResults {
248				assertResultEqual(t, "alpha#"+strconv.Itoa(i), res, wantAlpha)
249				if bytes.Contains(res.out, []byte("bravo")) {
250					t.Errorf("alpha#%d body leaks bravo", i)
251				}
252			}
253			for i, res := range bravoResults {
254				assertResultEqual(t, "bravo#"+strconv.Itoa(i), res, wantBravo)
255				if bytes.Contains(res.out, []byte("alpha")) {
256					t.Errorf("bravo#%d body leaks alpha", i)
257				}
258			}
259		}
260	
261		for iter := 0; iter < iterations; iter++ {
262			runBatch(iter%2 == 0)
263		}
264	
265		// Post-batch retries through the same shared Adapter keep each tree's
266		// own result, in either order, and repeat stably.
267		assertResultEqual(t, "post-batch alpha", runAdapt(t, shared, alphaRoot, aBody), wantAlpha)
268		assertResultEqual(t, "post-batch bravo", runAdapt(t, shared, bravoRoot, bBody), wantBravo)
269		assertResultEqual(t, "post-batch bravo again", runAdapt(t, shared, bravoRoot, bBody), wantBravo)
270		assertResultEqual(t, "post-batch alpha again", runAdapt(t, shared, alphaRoot, aBody), wantAlpha)
271	}
272	
273	// TestAdaptConcurrentFailureIsolation mixes a failing tree (an import cycle
274	// or a syntax error) with the successful order-reordered tree. Failures
275	// return no partial body and name only their own file chain; the successful
276	// tree is unaffected. The same shared Adapter is then reused for
277	// fail -> repair -> succeed -> re-break -> fail.
278	func TestAdaptConcurrentFailureIsolation(t *testing.T) {
279		const workers = 6
280	
281		alphaDir := t.TempDir()
282		writeOrderTree(t, alphaDir, "alpha-iso")
283		alphaRoot := filepath.Join(alphaDir, "Caddyfile")
284		aBody := alphaBody()
285		wantAlpha := runAdapt(t, caddyfile.Adapter{ServerType: ServerType{}}, alphaRoot, aBody)
286		if wantAlpha.err != nil {
287			t.Fatalf("alpha reference failed: %v", wantAlpha.err)
288		}
289	
290		type fault struct {
291			name     string
292			snippets []string
293			break_   func(t *testing.T, target, link string)
294			repair   func(t *testing.T, target, link string)
295		}
296		faults := []fault{
297			{
298				name:     "cycle",
299				snippets: []string{"import cycle detected", "target.caddy", "loop-link.caddy"},
300				break_: func(t *testing.T, target, link string) {
301					writeAdaptFile(t, target, "import loop-link.caddy\n")
302					if err := os.Symlink(target, link); err != nil && !os.IsExist(err) {
303						t.Skipf("cannot create symlink: %v", err)
304					}
305				},
306				repair: func(t *testing.T, target, link string) {
307					if err := os.Remove(link); err != nil && !os.IsNotExist(err) {
308						t.Fatalf("remove link: %v", err)
309					}
310					writeAdaptFile(t, target, "charlie-fixed.example {\n\trespond \"FIXED\"\n}\n")
311				},
312			},
313			{
314				name:     "syntax",
315				snippets: []string{"syntax error"},
316				break_: func(t *testing.T, target, _ string) {
317					writeAdaptFile(t, target, "charlie-broken.example {\n")
318				},
319				repair: func(t *testing.T, target, _ string) {
320					writeAdaptFile(t, target, "charlie-fixed.example {\n\trespond \"FIXED\"\n}\n")
321				},
322			},
323		}
324	
325		for _, f := range faults {
326			t.Run(f.name, func(t *testing.T) {
327				charlieDir := t.TempDir()
328				charlieRoot := filepath.Join(charlieDir, "Caddyfile")
329				target := filepath.Join(charlieDir, "charlie", "target.caddy")
330				link := filepath.Join(charlieDir, "charlie", "loop-link.caddy")
331				writeAdaptFile(t, filepath.Join(charlieDir, "charlie", "entry.caddy"), "import target.caddy\n")
332				writeAdaptFile(t, charlieRoot, "import charlie/entry.caddy\n")
333				f.break_(t, target, link)
334				cBody := []byte("import charlie/entry.caddy\n")
335	
336				wantFail := runAdapt(t, caddyfile.Adapter{ServerType: ServerType{}}, charlieRoot, cBody)
337				if wantFail.err == nil {
338					t.Fatal("reference failure unexpectedly succeeded")
339				}
340				if wantFail.out != nil {
341					t.Fatal("reference failure returned a partial body")
342				}
343	
344				shared := caddyfile.Adapter{ServerType: ServerType{}}
345				start := make(chan struct{})
346				var wg sync.WaitGroup
347				var mu sync.Mutex
348				var oks, fails []adaptResult
349				for i := 0; i < workers; i++ {
350					wg.Add(2)
351					go func() {
352						defer wg.Done()
353						<-start
354						r := runAdapt(t, shared, alphaRoot, aBody)
355						mu.Lock()
356						oks = append(oks, r)
357						mu.Unlock()
358					}()
359					go func() {
360						defer wg.Done()
361						<-start
362						r := runAdapt(t, shared, charlieRoot, cBody)
363						mu.Lock()
364						fails = append(fails, r)
365						mu.Unlock()
366					}()
367				}
368				close(start)
369				wg.Wait()
370	
371				if len(oks) != workers || len(fails) != workers {
372					t.Fatalf("expected %d of each, got %d ok / %d fail", workers, len(oks), len(fails))
373				}
374				for i, r := range oks {
375					assertResultEqual(t, "success#"+strconv.Itoa(i), r, wantAlpha)
376				}
377				for i, r := range fails {
378					label := "failure#" + strconv.Itoa(i)
379					if r.err == nil {
380						t.Errorf("%s: expected failure, got body %s", label, r.out)
381						continue
382					}
383					if r.out != nil {
384						t.Errorf("%s: partial body on failure (%d bytes)", label, len(r.out))
385					}
386					if r.err.Error() != wantFail.err.Error() {
387						t.Errorf("%s: error text drift\nwant: %s\ngot:  %s", label, wantFail.err, r.err)
388					}
389					msg := r.err.Error()
390					for _, snippet := range f.snippets {
391						if !strings.Contains(msg, snippet) {
392							t.Errorf("%s: error %q missing %q", label, msg, snippet)
393						}
394					}
395					if !strings.Contains(msg, charlieDir) {
396						t.Errorf("%s: error does not name its own tree: %s", label, msg)
397					}
398					if strings.Contains(msg, alphaDir) {
399						t.Errorf("%s: error leaks the successful tree's path: %s", label, msg)
400					}
401				}
402	
403				// retry failure, then repair: only repaired calls succeed, and a
404				// fresh adapter produces the same repaired result.
405				if r := runAdapt(t, shared, charlieRoot, cBody); r.err == nil {
406					t.Fatal("failure must persist on immediate retry")
407				}
408				f.repair(t, target, link)
409				wantFixed := runAdapt(t, caddyfile.Adapter{ServerType: ServerType{}}, charlieRoot, cBody)
410				if wantFixed.err != nil {
411					t.Fatalf("repaired reference failed: %v", wantFixed.err)
412				}
413				assertResultEqual(t, "repaired", runAdapt(t, shared, charlieRoot, cBody), wantFixed)
414				assertResultEqual(t, "alpha after repair", runAdapt(t, shared, alphaRoot, aBody), wantAlpha)
415	
416				// re-break: fails again with the same category and chain.
417				f.break_(t, target, link)
418				gotFail := runAdapt(t, shared, charlieRoot, cBody)
419				if gotFail.err == nil {
420					t.Fatal("re-broken tree unexpectedly succeeded")
421				}
422				if gotFail.err.Error() != wantFail.err.Error() {
423					t.Errorf("re-broken error drift\nwant: %s\ngot:  %s", wantFail.err, gotFail.err)
424				}
425				assertResultEqual(t, "alpha after re-break", runAdapt(t, shared, alphaRoot, aBody), wantAlpha)
426			})
427		}
428	}
429	
430	func writeAdaptFile(t *testing.T, path, content string) {
431		t.Helper()
432		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
433			t.Fatalf("mkdir %s: %v", path, err)
434		}
435		if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
436			t.Fatalf("write %s: %v", path, err)
437		}
438	}
439	
440	// TestAdaptOrderOptionIsLocalToAdaptation covers two ordering semantics that
441	// used to rely on a process-wide mutation: (1) several "order" options in one
442	// global block compose within that adaptation, and (2) a later adaptation
443	// without the option still uses the baseline rather than inheriting the
444	// earlier call's order. Repeating the ordered adaptation must be stable too.
445	func TestAdaptOrderOptionIsLocalToAdaptation(t *testing.T) {
446		ordered := []byte(`{
447		order respond first
448		order redir last
449	}
450	ordered-iso.example {
451		vars x 1
452		redir /a /b
453		respond "O"
454	}
455	`)
456		plain := []byte(`plain-iso.example {
457		redir /a /b
458		respond "P"
459	}
460	`)
461		adapter := caddyfile.Adapter{ServerType: ServerType{}}
462	
463		var first []byte
464		for i := 0; i < 3; i++ {
465			out, _, err := adapter.Adapt(ordered, nil)
466			if err != nil {
467				t.Fatalf("ordered adapt %d: %v", i, err)
468			}
469			order := redirRespondOrder(t, out)
470			if order[0] != "respond" || order[len(order)-1] != "redir" {
471				t.Fatalf("ordered adapt %d: expected respond first and redir last, got %v", i, order)
472			}
473			if first == nil {
474				first = out
475			} else if !bytes.Equal(out, first) {
476				t.Fatalf("ordered adapt %d drifted from the first", i)
477			}
478		}
479	
480		// a subsequent adaptation with no "order" option must not inherit it
481		out, _, err := adapter.Adapt(plain, nil)
482		if err != nil {
483			t.Fatalf("plain adapt: %v", err)
484		}
485		order := redirRespondOrder(t, out)
486		if order[0] != "redir" {
487			t.Fatalf("plain adaptation inherited reordered directive order, got %v", order)
488		}
489	}
