// before/after/first/last constraints of one adaptation into a single stable
// order. The constraints form directed edges in an ordering graph that also
// contains the baseline as a chain; the result is the total ordering with
// the smallest baseline ranks that honors every edge, so swapping
// declaration lines, import traversal order or glob order cannot change the
// result as long as the constraint set is equivalent. Unrelated directives
// keep their baseline order.
func resolveDirectiveOrder(baseline []string, constraints orderConstraints) ([]string, error) {
	// rank of each node in the baseline; directives absent from the
	// baseline sort after all baseline directives, ordered by the first
	// time they appear in the constraints
	baselineRank := make(map[string]int)
	for i, dir := range baseline {
		baselineRank[dir] = i
	}
	nextRank := len(baseline)
	rankOf := func(dir string) {
		if _, ok := baselineRank[dir]; !ok {
			baselineRank[dir] = nextRank
			nextRank++
		}
	}
	for _, c := range constraints {
		rankOf(c.dir)
		if c.otherDir != "" {
			rankOf(c.otherDir)
		}
	}

	// every edge is tagged with the constraint that declared it; the zero
	// value marks an edge implied by the baseline chain, which must never be
	// reported as the user's contradiction
	type edge struct{ from, to string }
	origin := make(map[edge]orderConstraint)
	addEdge := func(from, to string, c orderConstraint) error {
		e := edge{from, to}
		if existing, ok := origin[e]; ok {
			// identical declaration repeated: idempotent, keep the first
			// occurrence so diagnostics are stable
			if existing == (orderConstraint{}) || c == existing {
				return nil
			}
			return nil
		}
		if reverse, ok := origin[edge{to, from}]; ok && reverse != (orderConstraint{}) {
			return fmt.Errorf("%s:%d: conflicting order: directive '%s' cannot be ordered %s '%s' as well as %s '%s' (%s:%d)",
				c.file, c.line, to, c.pos, from, reverse.pos, reverse.otherDir, reverse.file, reverse.line)
		}
		origin[e] = c
		return nil
	}

	// encode the baseline as a chain of edges so unconstrained directives
	// retain their default position relative to one another
	for i := 1; i < len(baseline); i++ {
		origin[edge{baseline[i-1], baseline[i]}] = orderConstraint{}
	}

	// nodes fixed first or last relate to every other known node; collect
	// their edges up front so later constraints are checked against them too
	nodes := make([]string, 0, len(baselineRank))
	for dir := range baselineRank {
		nodes = append(nodes, dir)
	}
	sort.Slice(nodes, func(i, j int) bool { return baselineRank[nodes[i]] < baselineRank[nodes[j]] })

	// apply each constraint; a contradiction with a previously declared
	// edge in the opposite direction is reported at the new declaration
	for _, c := range constraints {
		switch c.pos {
		case Before:
			if err := addEdge(c.dir, c.otherDir, c); err != nil {
				return nil, err
			}
		case After:
			if err := addEdge(c.otherDir, c.dir, c); err != nil {
				return nil, err
			}
		case First:
			for _, node := range nodes {
				if node == c.dir {
					continue
				}
				if err := addEdge(c.dir, node, c); err != nil {
					return nil, err
				}
			}
		case Last:
			for _, node := range nodes {
				if node == c.dir {
					continue
				}
				if err := addEdge(node, c.dir, c); err != nil {
					return nil, err
				}
			}
		default:
			return nil, fmt.Errorf("%s:%d: unknown positional '%s'", c.file, c.line, c.pos)
		}
	}

	// build adjacency lists and in-degrees from the edge set
	succ := make(map[string][]string, len(nodes))
	indeg := make(map[string]int, len(nodes))
	for _, node := range nodes {
		indeg[node] = 0
	}
	for e := range origin {
		succ[e.from] = append(succ[e.from], e.to)
		indeg[e.to]++
	}
	for from := range succ {
		sort.Slice(succ[from], func(i, j int) bool { return baselineRank[succ[from][i]] < baselineRank[succ[from][j]] })
	}

	// Kahn's algorithm; among ready nodes always take the one with the
	// smallest baseline rank, which makes the output independent of the
	// order in which constraints or edges were collected
	ready := make([]string, 0, len(nodes))
	for _, node := range nodes {
		if indeg[node] == 0 {
			ready = append(ready, node)
		}
	}
	ordered := make([]string, 0, len(nodes))
	for len(ready) > 0 {
		cur := ready[0]
		ready = ready[1:]
		ordered = append(ordered, cur)
		for _, next := range succ[cur] {
			indeg[next]--
			if indeg[next] == 0 {
				ready = append(ready, next)
				sort.Slice(ready, func(i, j int) bool { return baselineRank[ready[i]] < baselineRank[ready[j]] })
			}
