// resolveDirectiveOrder merges the baseline directive order with the
// before/after/first/last constraints of one adaptation into a single stable
// order. The constraints form a directed graph; the baseline is not part of
// that graph, it only supplies the tiebreak. A topological sort that always
// emits the available directive with the smallest baseline rank yields the
// ordering closest to the baseline while honoring every declared edge: a
// directive moved before/after an anchor lands adjacent to it, and
// directives untouched by the constraints keep their default relative
// positions. Because the graph is complete before sorting, the result does
// not depend on the order in which the edges were declared, the order in
// which unconstrained directives appeared in the Caddyfile, or the order in
// which imports were traversed.
func resolveDirectiveOrder(baseline []string, constraints orderConstraints) ([]string, error) {
	// rank of each node in the baseline; directives absent from the
	// baseline (plugins without a registered default position, or
	// directives only mentioned as ordering targets) sort after all
	// baseline directives and tiebreak lexicographically among themselves,
	// so their relative order never depends on declaration order
	baselineRank := make(map[string]int)
	for i, dir := range baseline {
		baselineRank[dir] = i
	}
	for _, c := range constraints {
		if _, ok := baselineRank[c.dir]; !ok {
			baselineRank[c.dir] = -1
		}
		if c.otherDir != "" {
			if _, ok := baselineRank[c.otherDir]; !ok {
				baselineRank[c.otherDir] = -1
			}
		}
	}
	nodes := make([]string, 0, len(baselineRank))
	for dir := range baselineRank {
		nodes = append(nodes, dir)
	}
	less := func(a, b string) bool {
		ra, rb := baselineRank[a], baselineRank[b]
		switch {
		case ra < 0 && rb < 0:
			return a < b
		case ra < 0:
			return false
		case rb < 0:
			return true
		default:
			return ra < rb
		}
	}
	sort.Slice(nodes, func(i, j int) bool { return less(nodes[i], nodes[j]) })

	// every user-declared edge remembers its first declaration so reverse
	// edges can be reported at both ends
	type edge struct{ from, to string }
	origin := make(map[edge]orderConstraint)
	addEdge := func(from, to string, c orderConstraint) error {
		e := edge{from, to}
		if existing, ok := origin[e]; ok {
			// the same relation declared again is idempotent; keep the
			// first occurrence for stable diagnostics
			_ = existing
			return nil
		}
		if reverse, ok := origin[edge{to, from}]; ok {
			return fmt.Errorf("%s:%d: conflicting order for directives '%s' and '%s': %s %s %s here, but %s %s %s at %s:%d",
				c.file, c.line, from, to,
				c.dir, c.pos, edgeOther(c, from, to),
				reverse.dir, reverse.pos, edgeOther(reverse, to, from), reverse.file, reverse.line)
		}
		origin[e] = c
		return nil
	}

