package httpcaddyfile

import (
	"fmt"
	"testing"
)

func scratchC(dir, pos, other string, line int) orderConstraint {
	c := orderConstraint{dir: dir, pos: Positional(pos), file: "Caddyfile", line: line}
	c.otherDir = other
	return c
}

func TestScratchResolve(t *testing.T) {
	base := []string{"map", "root", "header", "redir", "method", "rewrite", "handle", "respond", "file_server"}

	cases := []struct {
		name        string
		constraints orderConstraints
		want        string
	}{
		{"respond before redir", orderConstraints{
			scratchC("respond", "before", "redir", 2),
		}, "map root header respond redir method rewrite handle file_server"},
		{"respond after header", orderConstraints{
			scratchC("respond", "after", "header", 2),
		}, "map root header respond redir method rewrite handle file_server"},
		{"root first", orderConstraints{
			scratchC("root", "first", "", 2),
		}, "root map header redir method rewrite handle respond file_server"},
		{"method last", orderConstraints{
			scratchC("method", "last", "", 2),
		}, "map root header redir rewrite handle respond file_server method"},
		{"chain vars before method; respond after vars (vars absent? vars is baseline here no)", orderConstraints{
			scratchC("respond", "before", "method", 2),
			scratchC("redir", "before", "respond", 3),
		}, "map root header redir respond method rewrite handle file_server"},
		{"extra plugin after root", orderConstraints{
			scratchC("myplugin", "after", "root", 2),
		}, "map root myplugin header redir method rewrite handle respond file_server"},
	}
	for _, tc := range cases {
		got, err := resolveDirectiveOrder(base, tc.constraints)
		if err != nil {
			t.Fatalf("%s: %v", tc.name, err)
		}
		joined := joinSpaces(got)
		if joined != tc.want {
			t.Errorf("%s:\n got %s\nwant %s", tc.name, joined, tc.want)
		}
	}

	// permutation invariance
	cs := orderConstraints{
		scratchC("respond", "before", "method", 2),
		scratchC("redir", "after", "header", 3),
		scratchC("rewrite", "before", "respond", 4),
	}
	var first string
	for perm := range [][3]int{{0, 1, 2}, {2, 1, 0}, {1, 0, 2}, {2, 0, 1}, {1, 2, 0}, {0, 2, 1}} {
		p := orderConstraints{cs[perm[0]], cs[perm[1]], cs[perm[2]]}
		// renumber lines to emulate swapped lines
		for i := range p {
			p[i].line = i + 2
		}
		got, err := resolveDirectiveOrder(base, p)
		if err != nil {
			t.Fatalf("perm %v: %v", perm, err)
		}
		s := joinSpaces(got)
		if first == "" {
			first = s
		} else if s != first {
			t.Errorf("perm %v: %s != %s", perm, s, first)
		}
	}
	fmt.Println("permutation-invariant result:", first)

	// contradiction
	_, err := resolveDirectiveOrder(base, orderConstraints{
		scratchC("respond", "before", "redir", 2),
		scratchC("redir", "before", "respond", 3),
	})
	if err == nil {
		t.Fatal("expected contradiction error")
	}
	t.Logf("contradiction: %v", err)

	// indirect cycle
	_, err = resolveDirectiveOrder(base, orderConstraints{
		scratchC("respond", "before", "redir", 2),
		scratchC("redir", "before", "method", 3),
		scratchC("method", "before", "respond", 4),
	})
	if err == nil {
		t.Fatal("expected cycle error")
	}
	t.Logf("cycle: %v", err)
}

func joinSpaces(s []string) string {
	out := ""
	for i, v := range s {
		if i > 0 {
			out += " "
		}
		out += v
	}
	return out
}

