	for e, c := range origin {
		succ[e.from] = append(succ[e.from], e.to)
		pred[e.to] = append(pred[e.to], e.from)
		indeg[e.to]++
		if c.otherDir != "" {
			singleSucc[e.from] = append(singleSucc[e.from], e.to)
			singlePred[e.to] = append(singlePred[e.to], e.from)
		}
	}
	rankLess := func(a, b string) bool { return rank[a] < rank[b] }
	for n := range succ {
		sort.Slice(succ[n], func(i, j int) bool { return rankLess(succ[n][i], succ[n][j]) })
		sort.Slice(pred[n], func(i, j int) bool { return rankLess(pred[n][i], pred[n][j]) })
		sort.Slice(singleSucc[n], func(i, j int) bool { return rankLess(singleSucc[n][i], singleSucc[n][j]) })
		sort.Slice(singlePred[n], func(i, j int) bool { return rankLess(singlePred[n][i], singlePred[n][j]) })
	}

	// reject cycles before emitting; a graph with a cycle has no valid order
	remaining := make(map[string]int, len(nodes))
	for node, d := range indeg {
		remaining[node] = d
	}
	queue := make([]string, 0, len(nodes))
	for _, node := range nodes {
		if remaining[node] == 0 {
			queue = append(queue, node)
		}
	}
	visited := 0
	for len(queue) > 0 {
		cur := queue[0]
		queue = queue[1:]
		visited++
		for _, next := range succ[cur] {
			remaining[next]--
			if remaining[next] == 0 {
				queue = append(queue, next)
			}
		}
	}
	if visited != len(nodes) {
		return nil, orderCycleError(nodes, succ, remaining, rankLess, origin)
	}

	// emit first-section directives (baseline-rank tiebreak; the section as
	// a whole precedes everything else, regardless of declaration order)
	emitted := make(map[string]bool, len(nodes))
	ordered := make([]string, 0, len(nodes))
	var sectionDirs []string
	for dir := range firstDirs {
		sectionDirs = append(sectionDirs, dir)
	}
	sort.Slice(sectionDirs, func(i, j int) bool { return rankLess(sectionDirs[i], sectionDirs[j]) })
	for _, dir := range sectionDirs {
		emitted[dir] = true
		ordered = append(ordered, dir)
	}

	// emit the remaining directives in baseline order with constraint-driven
	// adjacency: before emitting a node, every directive constrained before
	// it by a single anchor is pulled up (recursively) first; right after
	// emitting a node, a directive constrained after it whose anchors have
	// all been emitted is pushed down next to it. Directives the constraints
	// do not touch keep their default positions. Baseline order drives the
	// scan, which is what makes the result independent of declaration and
	// import order; non-baseline directives are pulled or pushed along with
	// their anchors.
	allSinglePredsEmitted := func(node string) bool {
		for _, prerequisite := range singlePred[node] {
			if !emitted[prerequisite] {
				return false
			}
		}
		return true
	}
	var visit func(string)
	visit = func(node string) {
		// mark on entry: a prerequisite pull followed by a push-down can
		// re-enter this same node before its outer call has finished
		if emitted[node] {
			return
		}
		emitted[node] = true
		for _, prerequisite := range singlePred[node] {
			visit(prerequisite)
		}
		ordered = append(ordered, node)
		for _, successor := range singleSucc[node] {
			// only place an "after" subject once every one of its anchors
			// has been emitted, or pulling it here would drag a later
			// anchor out of position
			if !emitted[successor] && allSinglePredsEmitted(successor) {
				visit(successor)
			}
		}
	}
	for _, node := range nodes {
		visit(node)
	}

	// last-section directives come after everything else, rank tiebreak
	sectionDirs = sectionDirs[:0]
	for dir := range lastDirs {
		sectionDirs = append(sectionDirs, dir)
	}
	sort.Slice(sectionDirs, func(i, j int) bool { return rankLess(sectionDirs[i], sectionDirs[j]) })
	for _, dir := range sectionDirs {
		// a last directive was already skipped during the middle scan;
		// append it once
		if !slices.Contains(ordered, dir) {
			ordered = append(ordered, dir)
		}
	}

	return ordered, nil
}

