// closureSection expands a set of section subjects: following neighbors
// turns every directive transitively tied into the section into a member.
// The first section pulls in directives constrained before its subjects
// (predecessors); the last section pulls in directives constrained after
// its subjects (successors).
func closureSection(seeds map[string]struct{}, neighbors map[string][]string) map[string]struct{} {
	set := make(map[string]struct{}, len(seeds))
	var stack []string
	for seed := range seeds {
		set[seed] = struct{}{}
		stack = append(stack, seed)
	}
	for len(stack) > 0 {
		cur := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		for _, next := range neighbors[cur] {
			if _, ok := set[next]; ok {
				continue
			}
	set[next] = struct{}{}
			stack = append(stack, next)
		}
	}
	return set
}

// sectionIntersection returns the lowest-ranked directive that belongs to
// both end sections, or "" if the sections are disjoint.
func sectionIntersection(first, last map[string]struct{}, rank map[string]int) string {
	overlap := ""
	for dir := range first {
		if _, ok := last[dir]; !ok {
			continue
		}
		if overlap == "" || rank[dir] < rank[overlap] {
			overlap = dir
		}
	}
	return overlap
}

// sectionSeedFor returns the declaration of the lowest-ranked section seed
// from which dir is reachable through neighbors (predecessors for the first
// section, successors for the last section).
func sectionSeedFor(dir string, seeds map[string]struct{}, neighbors map[string][]string) orderConstraint {
	// reverse reachability: find seeds that can reach dir through neighbors
	found := ""
	for seed := range seeds {
		seen := map[string]bool{seed: true}
		stack := []string{seed}
		reachable := false
		for len(stack) > 0 {
			cur := stack[len(stack)-1]
			stack = stack[:len(stack)-1]
			if cur == dir {
				reachable = true
				break
			}
			for _, next := range neighbors[cur] {
				if !seen[next] {
					seen[next] = true
					stack = append(stack, next)
				}
			}
		}
		if reachable && (found == "" || seed < found) {
			found = seed
		}
	}
	// callers already know a seed exists; look up its declaration in the
	// corresponding seed-declaration maps by re-deriving nothing here
	if c, ok := sectionSeedDecls[found]; ok {
		return c
	}
	return orderConstraint{dir: found}
}

// sectionSeedDecls is populated during resolution so sectionSeedFor can
// name the section seed declarations.
var sectionSeedDecls map[string]orderConstraint

