// constraints reach the site's top-level chain but never into route,
// handle or handle_errors blocks: those keep their own baseline-local
// ordering regardless of how textually their directives appear.
func TestAdaptOrderDoesNotReorderNestedScopes(t *testing.T) {
	body := `{
	order respond before redir
}
nested-order.example {
	handle {
		respond "N"
		redir /n /x
	}
	handle_errors {
		respond "E"
		redir /e /y
	}
	route {
		respond "R"
		redir /r /z
	}
	redir /t /q
	respond "T"
}
`
	out := mustAdapt(t, body)
	depths := staticByDepth(t, out)

	top, ok := depths[1]
	if !ok {
		t.Fatalf("no top-level handlers found: %#v", depths)
	}
	if !strings.Contains(strings.Join(top, ","), "respond:T") ||
		indexOf(top, "respond:T") > indexOf(top, "redir") {
		t.Errorf("top-level chain not reordered: %v", top)
	}

	nested, ok := depths[2]
	if !ok {
		t.Fatalf("no nested handlers found: %#v", depths)
	}
	// inside handle and route, baseline order (redir before respond) wins
	if len(nested) < 4 ||
		nested[0] != "redir" || nested[1] != "respond:N" ||
		nested[2] != "redir" || nested[3] != "respond:R" {
		t.Errorf("nested route/handle chains were reordered by outer order: %v", nested)
	}

	errChain, ok := depths[3]
	if !ok {
		t.Fatalf("no handle_errors handlers found: %#v", depths)
	}
	if len(errChain) < 2 || errChain[0] != "redir" || errChain[1] != "respond:E" {
		t.Errorf("handle_errors chain was reordered by outer order: %v", errChain)
	}
}

