// chainsByOrigin splits the static_response classification into the site's
// top-level chain, chains nested inside regular routes (route/handle
// blocks), and the handle_errors chain.
func chainsByOrigin(t *testing.T, out []byte) (top []string, nested []string, errChain []string) {
	t.Helper()
	var doc struct {
		Apps struct {
			HTTP struct {
				Servers map[string]dynServer `json:"servers"`
			} `json:"http"`
		} `json:"apps"`
	}
	if err := json.Unmarshal(out, &doc); err != nil {
		t.Fatalf("unmarshal adapted JSON: %v\n%s", err, out)
	}
	for _, srv := range doc.Apps.HTTP.Servers {
		for _, route := range srv.Routes {
			for _, h := range route.HandlersRaw {
				switch h.Handler {
				case "static_response":
					if kind, ok := classifyHandler(h); ok {
						top = append(top, kind)
					}
				case "subroute":
					sink := make(map[int][]string)
					for _, r := range h.Routes {
						walkStaticResponses(r.HandlersRaw, 1, sink)
					}
					for depth, vals := range sink {
						if depth >= 2 {
							nested = append(nested, vals...)
						} else {
							top = append(top, vals...)
						}
					}
				}
			}
		}
		if srv.Errors != nil {
			sink := make(map[int][]string)
			for _, route := range srv.Errors.Routes {
				walkStaticResponses(route.HandlersRaw, 0, sink)
			}
			// the errors route wraps the user subroute in another subroute,
			// so user directives are one level deeper than the regular ones
			for depth, vals := range sink {
				if depth >= 2 {
					errChain = append(errChain, vals...)
				}
			}
		}
	}
	return top, nested, errChain
}

// TestAdaptOrderDoesNotReorderNestedScopes verifies that outer "order"
// constraints reach the site's top-level chain but never into route,
// handle or handle_errors blocks: handle/handle_errors keep their baseline
// local order and route keeps its written local order regardless of the
// outer declaration.
func TestAdaptOrderDoesNotReorderNestedScopes(t *testing.T) {
	body := `{
	order respond before redir
}
nested-order.example {
	handle {
		respond "N"
		redir /n /x
	}
	handle_errors {
		respond "E"
		redir /e /y
	}
	route {
		respond "R"
		redir /r /z
	}
	redir /t /q
	respond "T"
}
`
	out := mustAdapt(t, body)
	top, nested, errChain := chainsByOrigin(t, out)

	// top-level chain is reordered by the global edge
	if indexOf(top, "respond:T") < 0 || indexOf(top, "respond:T") > indexOf(top, "redir") {
		t.Errorf("top-level chain not reordered: %v", top)
	}

	// handle sorts by the baseline local order (redir before respond) even
	// though the directives were written the other way around
	var handleChain []string
	for _, kind := range nested {
		if strings.HasSuffix(kind, "N") || (kind == "redir" && len(handleChain) < 2) {
			handleChain = append(handleChain, kind)
		}
	}
	handleChain = nil
	countRedir := 0
	for _, kind := range nested {
		switch {
		case kind == "respond:N":
			handleChain = append(handleChain, kind)
		case kind == "respond:R":
			// route preserves its written order: respond was written first
			if position(handleChain, "redir") >= 0 && countRedir == 0 {
				t.Errorf("handle block was not evaluated before route check")
			}
		}
		_ = kind
	}
	_ = countRedir

	// explicit, order-based checks: the handle pair is redir then
	// respond:N; the route pair keeps written order respond:R then redir
	atN := position(nested, "respond:N")
	atR := position(nested, "respond:R")
	if atN < 0 || atR < 0 {
		t.Fatalf("missing nested respond handlers: %v", nested)
	}
	redirsBeforeN := 0
	for i := 0; i < atN; i++ {
		if nested[i] == "redir" {
			redirsBeforeN++
		}
	}
	if redirsBeforeN != 1 {
		t.Errorf("handle block reordered by outer order (want redir before respond:N): %v", nested)
	}
	redirsBeforeR := 0
	for i := 0; i < atR; i++ {
		if nested[i] == "redir" {
			redirsBeforeR++
		}
	}
	if redirsBeforeR != 0 {
		t.Errorf("route block lost its written local order (want respond:R first): %v", nested)
	}

	// handle_errors keeps baseline local order (redir before respond:E)
	atE := position(errChain, "respond:E")
	if atE <= 0 || errChain[atE-1] != "redir" {
		t.Errorf("handle_errors chain reordered by outer order: %v", errChain)
	}
}

// position returns the index of v in s, or -1.
func position(s []string, v string) int {
	return indexOf(s, v)
}

