func TestAdaptOrderDoesNotReorderNestedScopes(t *testing.T) {
	t.Run("handle keeps baseline local order", func(t *testing.T) {
		body := `{
	order respond before redir
}
nested-handle.example {
	handle {
		respond "N"
		redir /n /x
	}
	redir /t /q
	respond "T"
}
